module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

parameter INITIAL = 2'b00;
parameter PULSE_START = 2'b01;
parameter PULSE_END = 2'b10;

reg [1:0] state;

reg [1:0] next_state;

always @(*) begin
    case(state)
        INITIAL: begin
            if(data_in == 1'b1) next_state = PULSE_START; else next_state = INITIAL;
        end
        PULSE_START: begin
            if(data_in == 1'b0) next_state = PULSE_END; else next_state = PULSE_START;
        end
        PULSE_END: begin
            if(data_in == 1'b1) next_state = PULSE_START; else next_state = INITIAL;
        end
        default: next_state = INITIAL;
    endcase
end

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        state <= INITIAL;
        data_out <= 1'b0;
    end else begin
        state <= next_state;
        if((state == PULSE_END) && (data_in == 1'b0))
            data_out <= 1'b1;
            data_out <= 1'b0;
    end
end
endmodule
